"use strict";(self.webpackChunkportfolio=self.webpackChunkportfolio||[]).push([["8666"],{3924(e){e.exports=JSON.parse('{"tag":{"label":"AWS","permalink":"/portfolio/projects/tags/aws","allTagsPath":"/portfolio/projects/tags","count":4,"items":[{"id":"side-projects/internal-data-platform","title":"Box2Home - Internal Data Platform","description":"Internal web app I built during my 2023 internship at Box2Home so developers could debug with production data. It replaced a paid third-party tool, with read-only, role-based access to 100+ production tables and a log of every query.","permalink":"/portfolio/projects/side-projects/internal-data-platform"},{"id":"work-projects/deploy-center/index","title":"DeployCenter - Multi-Tenant Kubernetes Deployment Platform","description":"Deployment platform I built for 20+ customer apps across 3 AWS regions. It cut per-app deploy time from 15 minutes to 3. I make batch changes from Git, developers deploy from a web dashboard, and both paths run the same Python orchestrator.","permalink":"/portfolio/projects/work-projects/deploy-center/"},{"id":"work-projects/observability/index","title":"Kubernetes Observability Stack","description":"Monitoring and alerting stack I built for production Kubernetes on AWS EKS. It cut mean time to resolve incidents (MTTR) by 50%, log storage cost by 70%, and alert volume by 60%, with Prometheus, Loki, Grafana OnCall, and external HTTPS probes.","permalink":"/portfolio/projects/work-projects/observability/"},{"id":"work-projects/scalable-bbb-aws/index","title":"Scalable BigBlueButton on AWS","description":"A video conferencing platform I designed and built on AWS at CraftSchoolship, running the open-source BigBlueButton software as an auto-scaling fleet. A custom machine image cut server launch time from 11 minutes to 3, and scale-in protection keeps live meetings running while the fleet shrinks.","permalink":"/portfolio/projects/work-projects/scalable-bbb-aws/"}],"unlisted":false}}')}}]);